/// <summary>
/// This is business logic class
/// CB387_DallasPickListRegistration
/// </summary>
final class METPickingListRegistrationPostingJob
{
                          
}

Method.Source:
    //Map selectedLines; //key wmsOrderTrans.recId, Value: WMSOrderTrans.orderid;//used to hit best index

    /// <summary>
    /// This method hold the posting logic
    /// </summary>
    /// <param name = "_contract">Contract</param>
    public void postPickListRegistration(METDallasPicklistRegContract _contract)
    {
        #OCCRetryCount
        container       conShipmentIds;
        container       conOrdTrans;
        WMSOrderTrans   orderTrans;
        int             i;
        Set             salesIdsToConfirm = new Set(Types::String);
        SetEnumerator   salesIdsToConfirmEnumerator;

        conOrdTrans = _contract.parmConOrderTrans();

        METProcMetrics procMetrics = METProcMetrics::construct(METBatchLogOperation::DallasPicklistRegistration);
        procMetrics.setTotalCount(conlen(conOrdTrans));
        procMetrics.beginTrace('Process started');

        using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
        {
            for (i=1; i <= conlen(conOrdTrans); i++)
            {
                try
                {
                    if (procMetrics)
                    {
                        procMetrics.ttsBeginTrace();
                        procMetrics.startDescriptionTime(2, "@MET:FinishPickingLine");
                    }
                    else
                    {
                        ttsbegin;
                    }
                    orderTrans = WMSOrderTrans::find(conpeek(conOrdTrans, i));
                    var selectedLine = new Map(Types::int64,Types::Container);
                    selectedLine.insert(orderTrans.RecId, [orderTrans.orderId, orderTrans.RecVersion]);

                    info(strFmt("%1, %2", orderTrans.orderId, orderTrans.routeId));
                    // Added condition to avoid exception if the ordertrans stuck in picked should not
                    // be processed again for picking as it is already picked and if we try to pick again it will throw error "WMSOrderTrans record with RecId %1 is already picked."
                    if (orderTrans.expeditionStatus != WMSExpeditionStatus::Picked)
                    {
                        WMSOrderTransType::finishPickingLinesMulti(selectedLine.pack(), '', orderTrans.wmsPickingRoute().OperatorWorker);
                    }
                
                    this.updateIsKegsItemSOTO(orderTrans);
                    
                    // Bug 193337: CB616 - "Trigger cancellation" button not triggering TMS processing
                    // reread the record otherwise the current buffer still has the previous status
                    orderTrans.reread();

                    if (orderTrans.inventTransType == InventTransType::Sales)
                    {                     
                        WMSPickingLineQty    qtyOrig    = METWMSOrderTrans::find(orderTrans.RecId).qtyOrig;
                        if (qtyOrig > orderTrans.qty)
                        {
                            METDallasPicklistRegPendingProcess::insertData(orderTrans.RecId, orderTrans.RouteId);
                        }
                    }
                    else if (orderTrans.inventTransType == InventTransType::TransferOrderShip)
                    {
                        InventTransferLine  inventTransferLine  = InventTransferLine::findTransIdShip(orderTrans.inventTransId, true);
                        if (inventTransferLine && inventTransferLine.QtyTransfer > orderTrans.qty && METInventTransferTableExt::isCampbellsWarehouse(inventTransferLine.inventDim().InventLocationId))
                        {
                            METDallasPicklistRegPendingProcess::insertData(orderTrans.RecId, orderTrans.RouteId);
                        }
                    }                    

                    // Bug 246341: CB387 - Dallas Picklist Registration - zero pick quantity is updating the picking list registration when importing using data entity Picklist registration entity
                    // For 0 pick, status updated to cancel, we also need to cancel the SO line deliver remainder.
                    // For picking list with multiple lines, status is updated to picked first, then when everything is processed status is updated to completed
                    if (orderTrans.expeditionStatus != WMSExpeditionStatus::Activated)
                    {
                        if (orderTrans.inventTransType == InventTransType::TransferOrderShip && this.isPickingListRegistrationCompleteForOrder(orderTrans))
                        {
                            //Added for Task 282558: CB913/CB162 - Campbells -Integration - Campbells Transfer Order Receipt
                            if (METCampbellTransferOrderProcessor::construct().processCampbellsTransferOrder(InventTransferTable::find(orderTrans.inventTransRefId), true) == false)
                            {
                                throw error (strFmt("@MET:ProcessFailedTO", orderTrans.inventTransRefId));
                            }
                        }
                    }

                    if (orderTrans.qty == 0)
                    {
                        METSalesOrderShipmentLoadLines  shipmentLoadLines;
 
                        while select forupdate shipmentLoadLines
                            where shipmentLoadLines.WMSOrderTransRecId == orderTrans.RecId
                        {
                            conShipmentIds += shipmentLoadLines.ShipmentId;
                            shipmentLoadLines.delete();
                        }
                    }
                    METSalesOrderShipmentLoadHeader::cleanShipmentIfNoLines(conShipmentIds);

                    if (procMetrics)
                    {
                        procMetrics.incDescriptionCount(2, 1);
                        procMetrics.ttsCommitTrace();
                        procMetrics.endDescriptionTime(2);
                    }
                    else
                    {
                        ttscommit;
                    }
                }
                catch(Exception::Deadlock)
                {
                    retry;
                }
                catch (Exception::UpdateConflict)
                {
                    if (appl.ttsLevel() == 0)
                    {
                        if (xSession::currentRetryCount() >= #RetryNum)
                        {
                            throw Exception::UpdateConflictNotRecovered;
                        }
                        else
                        {
                            retry;
                        }
                    }
                    else
                    {
                        throw Exception::UpdateConflict;
                    }
                }
                // Bug 246341: CB387 - Dallas Picklist Registration - zero pick quantity is updating the picking list registration when importing using data entity Picklist registration entity
                // Poor exception handling, if any errors go to the next picking list line to register
                catch(Exception::Error)
                {
                    error(strFmt("@MET:PickListPost", orderTrans.inventTransRefId));
                }

                procMetrics.incProcessedCountWithDocument(orderTrans.inventTransRefId);

            }

            procMetrics.endTrace();
        }


    }

    /// <summary>
    /// If the item on the sales line has a Product attribute listed in the new setup table, set IsKegItem = Yes
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <returns><c>boolean</c> object</returns>
    protected boolean isKegItem(ItemId    _itemId)
    {
        InventTable             inventTable;
        EcoResProductCategory   ecoResProductCategory;
        EcoResCategory          ecoResCategory;
        EcoResProduct           ecoResProduct;

        select firstonly RecId from ecoResCategory
            where ecoResCategory.METCartonsOrKegs == NoYes::Yes
        exists join ecoResProductCategory
            where ecoResProductCategory.Category == ecoResCategory.RecId
        exists join EcoResProduct
            where EcoResProduct.RecId == ecoResProductCategory.Product
        exists join InventTable
            where InventTable.Product == EcoResProduct.RecId
               && InventTable.ItemId  == _itemId;

        return ecoResCategory.RecId != 0;        
       
    }

    protected void updateIsKegsItemSOTO(WMSOrderTrans   _orderTrans)
    {
        SalesLine           salesLine;
        METSalesLine        metSalesLine;
        InventDim           inventDim;
        SalesTable          salesTable;
        SalesUpdateRemain   salesUpdateRemain;
        InventTransferLine  inventTransferLine;
        METInventTransferLine metInventTransferLine;

        switch (_orderTrans.inventTransType)
        {
            case InventTransType::Sales:
                select firstonly forupdate metSalesLine
                    exists join salesLine
                    where salesLine.InventTransId == _orderTrans.inventTransId
                        && metSalesLine.SalesLine == salesLine.RecId;

                if (metSalesLine.RecId)
                {
                    metSalesLine.skipBusinessEvents(true);                    

                    metSalesLine.IsKegItem = this.isKegItem(_orderTrans.ItemId);
                    metSalesLine.update();
                }
                break;

            case InventTransType::TransferOrderShip:
                select firstonly forupdate metInventTransferLine
                    exists join InventTransferLine
                    where InventTransferLine.InventTransId == _orderTrans.inventTransId
                       && metInventTransferLine.InventTransferLine == InventTransferLine.RecId;

                if (metInventTransferLine.RecId)
                {
                    metInventTransferLine.skipBusinessEvents(true);                   

                    metInventTransferLine.IsKegItem = this.isKegItem(_orderTrans.ItemId);
                    metInventTransferLine.update();
                }
                break;
        }
    }

    /// <summary>
    ///  Confirm sales order
    /// </summary>
    /// <param name = "_salesId">SalesId</param>
    /// <param name = "_procMetrics"> <c>METProcMetrics</c>.</param>
    public void salesOrderConfirm(SalesId _salesId, METProcMetrics _procMetrics)
    {
        #OCCRetryCount

        try
        {
            if (_procMetrics)
            {
                _procMetrics.startDescriptionTime(2, "@SYS330592");
            }

            SalesTable salesTable = SalesTable::find(_salesId);

            if (salesTable)
            {
                SalesFormLetter salesFormLetter = SalesFormLetter::construct(DocumentStatus::Confirmation);
                salesFormLetter.update(salesTable, DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), SalesUpdate::All);

                CustConfirmJour custConfirmJour;

                select firstonly custConfirmJour
                    order by RecId desc
                    where custConfirmJour.SalesId == _salesId;

                if (custConfirmJour.RecId)
                {
                    custConfirmJour.printJournal();
                }
            }

            if (_procMetrics)
            {
                _procMetrics.incDescriptionCount(2, 1);
                _procMetrics.endDescriptionTime(2);
            }
            
        }
        catch (Exception::DuplicateKeyException)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::DuplicateKeyExceptionNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::DuplicateKeyException;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            error(strFmt("@MET:DallasConfirmSalesOrdersError", _salesId));
        }
        
        _procMetrics.incProcessedCountWithDocument(_salesId);
    }

    /// <summary>
    /// This method returns if a picking list registration is completed for sales order
    /// </summary>
    /// <param name = "_salesId">Salesid</param>
    /// <returns>true or false</returns>
    public boolean isSalesPickingListRegistrationCompleted(SalesId _salesId)
    {
        SalesTable salesTable;
        WMSPickingRoute wmsPickingRoute;

        select firstonly RecId, SalesId from salesTable
            where salesTable.SalesType == SalesType::Sales
                && salesTable.SalesId == _salesId
            exists join wmsPickingRoute
                where wmsPickingRoute.transType == InventTransType::Sales
                && wmsPickingRoute.transRefId == salesTable.SalesId
                && wmsPickingRoute.expeditionStatus ==  WMSExpeditionStatus::Complete;

        return salesTable.RecId? true :false;
    }

    /// <summary>
    /// Checks if picking list registration completed for picking list registration record.
    /// </summary>
    /// <param name = "_orderTrans">WMSOrderTrans.</param>
    /// <returns>True if complete; otherwise, false.</returns>
    private boolean isPickingListRegistrationCompleteForOrder(WMSOrderTrans _orderTrans)
    {
        WMSPickingRoute pickingRoute;

        select firstonly RecId from pickingRoute
            where pickingRoute.PickingRouteID == _orderTrans.RouteId
            &&    pickingRoute.expeditionStatus == WMSExpeditionStatus::Complete;

        return (pickingRoute.RecId != 0);
    }

    /// <summary>
    /// Sales order confirmation in bundle
    /// </summary>
    /// <param name = "_contract">
    /// <c>METDallasPicklistRegSalesConfirmContract</c>
    /// </param>
    public void salesOrdersConfirmInBundle(METDallasPicklistRegSalesConfirmContract _contract)
    {
        container salesOrderCon = _contract.parmSalesOrderCon();
        METLegalEntityType metLegalEntityType = CompanyInfo::find().METLegalEntityType;

        METProcMetrics procMetrics = METProcMetrics::construct(METBatchLogOperation::DallasPicklistRegistration);
        procMetrics.setTotalCount(conlen(salesOrderCon));
        procMetrics.beginTrace('Process started');

        using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
        {
            for (int i = 1; i <= conlen(salesOrderCon); i++)
            {
                SalesId salesId = conpeek(salesOrderCon, i);

                if (metLegalEntityType != METLegalEntityType::None)
                {
                    this.salesOrderConfirm(salesId, procMetrics);
                }
            }

            procMetrics.endTrace();
        }
    }

    /// <summary>
    /// Determines whether the picklist registration for the specified order is complete and performs any required finalization.
    /// Verifies that all picklist lines for the order have been processed, updates related shipment/transfer state,
    /// triggers downstream processing (for example transfer-order post-processing), and records any pending actions.
    /// </summary>
    /// <param name="orderTrans">The order transaction record to evaluate and finalize.</param>
    /// <returns>
    /// True when the picklist registration for the order is complete and finalization succeeded; otherwise false.
    /// </returns>
    public void picklistRegistrationCompleteFinal(METDallasPicklistRegCompleteContract _contract)
    {
        METSalesOrderShipmentLoadLines      loadLine;
        WMSOrderTrans                       orderTrans;
        container                           allRoute = _contract.parmAllRouteIdCon();
        WMSPickingRouteID                   routeId;
        Set                                 processedShipmentIdSet = new Set(Types::String);

        for (int i = 1; i <= conlen(allRoute); i++)
        {
            routeId = conpeek(allRoute, i);

            while select ShipmentId from loadLine
                group by loadLine.ShipmentId
                where loadLine.ShipmentId
                exists join orderTrans
                    where orderTrans.RecId == loadLine.WMSOrderTransRecId
                        && orderTrans.routeId == routeId
            {
                if (!processedShipmentIdSet.in(loadLine.ShipmentId))
                {
                    processedShipmentIdSet.add(loadLine.ShipmentId);

                    METSalesOrderShipmentLoadHeader::updatePickComplete(loadLine.ShipmentId);
                }
            }
        }
    }

    /// <summary>
    /// This method is used to complete the picklist registration in bundle
    /// </summary>
    /// <param name = "_contract">
    /// <c>METDallasPicklistRegCompleteContract</c>.
    /// </param>
    public void picklistRegistrationCompleteInBundle(METDallasPicklistRegCompleteContract _contract)
    {
        #OCCRetryCount

        WMSPickingRoute wmsPickingRoute;
        WMSPickingRouteID pickingRouteId;

        container routeIdCon = _contract.parmRouteIdCon();

        METProcMetrics procMetrics = METProcMetrics::construct(METBatchLogOperation::DallasPicklistRegistration);
        procMetrics.setTotalCount(conlen(routeIdCon));
        procMetrics.beginTrace('Process started');

        using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
        {
            for (int i = 1; i <= conlen(routeIdCon); i++)
            {
                try
                {
                    if (procMetrics)
                    {
                        procMetrics.startDescriptionTime(2, "@MET:DallasPicklistRegComplete");
                    }
           
                    pickingRouteId = conpeek(routeIdCon, i);
                    
                    ttsBegin;
                    
                    wmsPickingRoute = WMSPickingRoute::find(pickingRouteId, true);
                    wmsPickingRoute.checkFinishRoute();

                    ttsCommit;

                    if (wmsPickingRoute.transType == InventTransType::TransferOrderShip && wmsPickingRoute.expeditionStatus == WMSExpeditionStatus::Complete)
                    {
                        ttsbegin;
                        //Added for Task 282558: CB913/CB162 - Campbells -Integration - Campbells Transfer Order Receipt
                        if (METCampbellTransferOrderProcessor::construct().processCampbellsTransferOrder(InventTransferTable::find(wmsPickingRoute.transRefId), true) == false)
                        {
                            throw error (strFmt("@MET:ProcessFailedTO", wmsPickingRoute.transRefId));
                        }

                        ttsCommit;
                    }
                  
                    if (procMetrics)
                    {
                        procMetrics.incDescriptionCount(2, 1);
                        procMetrics.endDescriptionTime(2);
                    }
                }
                catch(Exception::Deadlock)
                {
                    retry;
                }
                catch (Exception::UpdateConflict)
                {
                    if (appl.ttsLevel() == 0)
                    {
                        if (xSession::currentRetryCount() >= #RetryNum)
                        {
                            throw Exception::UpdateConflictNotRecovered;
                        }
                        else
                        {
                            retry;
                        }
                    }
                    else
                    {
                        throw Exception::UpdateConflict;
                    }
                }
                catch(Exception::Error)
                {
                    error(strFmt("@MET:PickListPost", wmsPickingRoute.transRefId));
                }

                procMetrics.incProcessedCountWithDocument(pickingRouteId);
            }

            procMetrics.endTrace();
        }

    }

    public void shortPickDeliveryReminderUpdInBundle(METDallasPicklistRegPendingProcessContract _contract)
    {
        #OCCRetryCount
        System.Exception ex;

        METDallasPicklistRegPendingProcess pendingProcess;
        WMSOrderTrans orderTrans;
        RefRecId pendingProcessRecId;

        container picklistPendingRecords = _contract.conPicklistPendingRecords();

        for (int i = 1; i <= conlen(picklistPendingRecords); i++)
        {
            pendingProcessRecId = conPeek(picklistPendingRecords, i);
            int     startLine = infologLine();

            try
            {
                ttsbegin;

                select firstonly forupdate pendingProcess
                    where pendingProcess.RecId == PendingProcessRecId;

                if (pendingProcess)
                {
                    pendingProcess.ProcessStartDateTime = DateTimeUtil::getSystemDateTime();
                    pendingProcess.Status = METOrderExtractionPendingProcessStatus::Processing;

                    orderTrans = WMSOrderTrans::find(pendingProcess.WMSOrderTransRecId);

                    if (orderTrans)
                    {
                        orderTrans.metShortPickDeliveryReminderUpd();
                    }

                    pendingProcess.ProcessEndDateTime = DateTimeUtil::getSystemDateTime();
                    pendingProcess.Status = METOrderExtractionPendingProcessStatus::Completed;

                    pendingProcess.update();
            
                }
                
                ttscommit;
            }
            catch (Exception::DuplicateKeyException)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::DuplicateKeyExceptionNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::DuplicateKeyException;
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::UpdateConflict;
                }
            }
            catch (ex)
            {
                select firstonly forupdate pendingProcess
                    where pendingProcess.RecId == PendingProcessRecId;

                if (pendingProcess)
                {
                    ttsbegin;

                    pendingProcess.Status = METOrderExtractionPendingProcessStatus::Failed;
                    pendingProcess.ProcessEndDateTime = DateTimeUtil::getSystemDateTime();
                    pendingProcess.RetryCount += 1;
                    pendingProcess.Error = METPickingListRegistrationPostingJob::getInfologSince(startLine);

                    pendingProcess.update();
                    ttscommit;
                }
            }
            
        }
    }

    /// <summary>
    /// Gets the infolog since the specified line number.
    /// </summary>
    /// <param name = "_fromLine">From line.</param>
    /// <returns>The infolog messages since the specified line number.</returns>
    public static str getInfologSince(int _fromLine)
    {
        container                con = infolog.copy(_fromLine + 1, infologLine());
        SysInfologEnumerator     enumerator = SysInfologEnumerator::newData(con);
        str                      ret;

        while (enumerator.moveNext())
        {
            ret += SysInfologMessageStruct::construct(enumerator.currentMessage()).message() + '\n';
        }
        return ret;
    }
